import json
import os
import xml.etree.ElementTree as ET
from typing import List, Optional, Set
from backend.app.services.theharvester.models import DiscoveredItem, DiscoveryBatch


class TheHarvesterParser:
    """Parses structured output files generated by theHarvester (JSONL primary, JSON fallback)."""

    @staticmethod
    def parse_output(prefix: str, target_domain: str) -> DiscoveryBatch:
        jsonl_file = f"{prefix}.jsonl"
        json_file = f"{prefix}.json"

        if os.path.exists(jsonl_file):
            return TheHarvesterParser.parse_jsonl_file(jsonl_file, target_domain)
        elif os.path.exists(json_file):
            return TheHarvesterParser.parse_json_file(json_file, target_domain)
        else:
            return DiscoveryBatch(domain=target_domain)

    @staticmethod
    def parse_jsonl_file(file_path: str, target_domain: str) -> DiscoveryBatch:
        if not os.path.exists(file_path):
            return DiscoveryBatch(domain=target_domain)

        items: List[DiscoveredItem] = []
        sources: Set[str] = set()

        with open(file_path, "r", encoding="utf-8", errors="replace") as f:
            raw_content = f.read()

        for line in raw_content.splitlines():
            line = line.strip()
            if not line:
                continue
            try:
                data = json.loads(line)
                rec_type = data.get("type")
                
                # Check for hostname record in JSONL
                if rec_type == "hostname":
                    val = data.get("value") or data.get("host") or data.get("hostname")
                    if val:
                        hostname = str(val).rstrip(".").lower()
                        rec_sources = data.get("sources", ["theHarvester"])
                        source_engine = rec_sources[0] if isinstance(rec_sources, list) and rec_sources else "theHarvester"
                        for s in (rec_sources if isinstance(rec_sources, list) else [rec_sources]):
                            sources.add(str(s))

                        items.append(
                            DiscoveredItem(
                                hostname=hostname,
                                domain=target_domain.lower(),
                                source="theHarvester",
                                source_engine=source_engine,
                                record_type="hostname",
                                raw_evidence_ref=f"JSONL_FILE:{file_path}",
                            )
                        )
                # Check for IP record in JSONL
                elif rec_type == "ip":
                    val = data.get("value") or data.get("ip")
                    if val:
                        rec_sources = data.get("sources", ["theHarvester"])
                        source_engine = rec_sources[0] if isinstance(rec_sources, list) and rec_sources else "theHarvester"
                        for s in (rec_sources if isinstance(rec_sources, list) else [rec_sources]):
                            sources.add(str(s))

                        items.append(
                            DiscoveredItem(
                                hostname=target_domain.lower(),
                                domain=target_domain.lower(),
                                source="theHarvester",
                                source_engine=source_engine,
                                record_type="ip",
                                ip_address=str(val),
                                raw_evidence_ref=f"JSONL_FILE:{file_path}",
                            )
                        )
            except Exception:
                continue

        # Deduplicate preserving order
        unique_items = []
        seen = set()
        for item in items:
            key = (item.hostname, item.record_type, item.ip_address or "")
            if key not in seen:
                seen.add(key)
                unique_items.append(item)

        return DiscoveryBatch(
            domain=target_domain,
            items=unique_items,
            total_discovered=len(unique_items),
            sources_used=sorted(list(sources)),
            raw_json_output=raw_content,
        )

    @staticmethod
    def parse_json_file(file_path: str, target_domain: str) -> DiscoveryBatch:
        if not os.path.exists(file_path):
            return DiscoveryBatch(domain=target_domain)

        with open(file_path, "r", encoding="utf-8", errors="replace") as f:
            raw_content = f.read()

        items: List[DiscoveredItem] = []
        sources: Set[str] = set()

        try:
            data = json.loads(raw_content)
            
            # Hostnames
            hosts = data.get("hosts", [])
            for host in hosts:
                if isinstance(host, str) and host.strip():
                    hostname = host.strip().rstrip(".").lower()
                    items.append(
                        DiscoveredItem(
                            hostname=hostname,
                            domain=target_domain.lower(),
                            source="theHarvester",
                            source_engine="theHarvester",
                            record_type="hostname",
                            raw_evidence_ref=f"JSON_FILE:{file_path}",
                        )
                    )
                    sources.add("theHarvester")

            # IPs
            ips = data.get("ips", [])
            for ip in ips:
                if isinstance(ip, str) and ip.strip():
                    items.append(
                        DiscoveredItem(
                            hostname=target_domain.lower(),
                            domain=target_domain.lower(),
                            source="theHarvester",
                            source_engine="theHarvester",
                            record_type="ip",
                            ip_address=ip.strip(),
                            raw_evidence_ref=f"JSON_FILE:{file_path}",
                        )
                    )
        except Exception:
            pass

        return DiscoveryBatch(
            domain=target_domain,
            items=items,
            total_discovered=len(items),
            sources_used=sorted(list(sources)),
            raw_json_output=raw_content,
        )
